from pathlib import Path
import json,shutil
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'experiments/D_era';pub=ROOT/'work/github-pages-peers2002';d=json.load(open(R/'tables/analysis.json'));style=(ROOT/'scripts/policy_report.template.html').read_text().split('<style>')[1].split('</style>')[0]
c={x['by']:x for x in d['cells'] if x['iso']=='CHN'}
t='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>换个年代 · 人生模拟实验室</title><style>__STYLE__</style></head><body><main><a href="index.html">← 人生模拟实验室</a><header><span class="eyebrow">D_ERA / ENGINE 0.8.30</span><h1>同一个人，换个年代</h1><p>1950、1960、1978、1991、2002、2020年出生的六种人生：同龄财富、全寿命、历史事件与物品记录分开看。</p><div class="grid"><div><div class="big">24,000</div><small>完整原始档案逐份核验</small></div><div><div class="big">4 × 6</div><small>四国六代，每格1,000局</small></div><div><div class="big">1,000</div><small>跨国家、跨年代重复使用的seed</small></div></div><nav><a href="#findings">主要发现</a><a href="#compare">同龄金额</a><a href="#history">历史与物品</a><a href="#cases">配对案例</a><a href="#method">方法与下载</a></nav></header>
<section id="findings"><h2>01 / 年代不是一个单独开关</h2>__FINDINGS__<p class="warn">这不是现实历史的因果估计。出生年改变人口、经济、教育与历史事件，也改变随机路径；预设人格相同不代表家庭和出生状态完全一致。所有2026年之后的部分都是未来模拟，含预测数据与引擎外推；2020年出生者的成年人生几乎全部属于此范围。</p></section>
<div class="controls"><label>出生国家 <select id="iso"></select></label><label>观察年龄 <select id="age"><option>24</option><option>30</option><option>35</option><option>40</option><option>50</option><option>65</option><option value="death">终局（各自去世时）</option></select></label><label>历史与物品出生年 <select id="cohort"></select></label></div>
<section id="compare"><h2>02 / 同龄金额，而非同一年金额</h2><p>内部金额×3.5为人民币中国购买力等价值；不是历史名义人民币，不是汇率，也不能视作已经完成跨年代现实物价校正。月均收入=年收入÷12。nwMed为净资产/所在地中位年收入，不是财富中位数倍数。</p><div id="money" class="scroll"></div><p class="note">各出生年用自身年龄快照；终局是各自死亡时，死亡年份不同。未来标记依据日历年>2026，仅帮助阅读，并不意味着2026年前的模拟值就是实测数据。</p><h3>同国家同seed：该出生年 − 2002年出生</h3><div id="pairs" class="scroll"></div><p class="note">只比较双方有相应年龄快照者，缺失不补零，负财富不剔除。P10/P90是个体差的分布，不是置信区间；差值中位数不是两臂中位数相减。</p><h3>样本流失</h3><div id="flow" class="scroll"></div><h3>六代均有快照：共同样本净资产</h3><div id="common" class="scroll"></div><p class="note">共同样本减少样本构成差异，但条件于六代均存活；小样本和幸存者偏差仍存在，不代表全部出生者。</p><h3>全部出生者的寿命与终局</h3><div id="life" class="scroll"></div><p class="note">包含未成年死亡；高等教育为edu≥4（大学/研究所）。摘要子女数可能含亡故或继子女，不是单纯生育数。去世年>2026的比例仅用于标注未来模拟覆盖。</p><h3>全体出生者寿命配对差</h3><div id="lifepairs" class="scroll"></div><h3>达到所选年龄的比例</h3><div id="survival" class="scroll"></div><p class="note">达到年龄按死亡年龄≥阈值计算，与快照可用数不一定相同。</p></section>
<section id="history"><h2>03 / 历史事件与物品记录下钻</h2><p>下列两表随国家与“历史与物品出生年”切换。历史文本来自原始log中kind=hist，并非所有历史影响都通过该标签记录；早期印度、尼日利亚等国家事件素材较少，不能将条目少解释成历史冲击小。</p><h3>历史文本出现最多的20项</h3><div id="hist" class="scroll"></div><p class="note">人数为出现过该文本的独立模拟人生数，次数为日志条目数。事件显示频率包含存活、年龄、迁移和触发条件选择，不能称为现实事件发生率。</p><h3>终局保留的物品取得年龄</h3><div id="items" class="scroll"></div><p class="warn">读取final.owns记录的年龄，不能统一称为人生首次拥有。尤其失去住房时引擎会删除owns.house，再取得时可能重新写入；缺失也不等于从未拥有。年龄分布只针对终局保留记录者，受到存活、年代技术供给与保留状态选择。</p><h3>实际出生状态相对预设人格的变化</h3><div id="audit" class="scroll"></div><p class="note">每格分母1,000，三项可重叠。1,000个seed的预设persona跨24格一致已核验；表中公开国别、年代出生逻辑产生的实际差异。</p></section>
<section id="cases"><h2>04 / 四国各看一组人生</h2><p>固定比较1960与2002年出生，按全部1,000对寿命差排序，取中位附近，同差按seed排序。没有只选成功或长寿者；每国两份日志均保留，不随顶部筛选改变。</p><div id="caseList"></div></section>
<section id="method"><h2>05 / 校验、证据与复算</h2><p>24,000个唯一ID与jobs计划完全相等；逐份读取gzip，核对seed、出生年、引擎版本与快照一致；摘要与原始文件在分析前后大小和修改时间一致。年龄分析不按未来成功、未来寿命筛选。</p><p>引擎年代数据文件注明来源包括UN WPP 2024、Maddison Project 2020、UN WUP 2018与Lee-Lee 2016，覆盖1950–2100；eraAt将查询年份限制在数据范围内。超出2100年的生命周期仍是模拟，并不意味着存在对应年份的独立数据。人口预测不是每个个体人生的预测，经济与其他机制还含模型规则。</p><p>无D前缀seed专属噪声对照。既有N1/N2仅作随机路径敏感性背景，不按编号假配对、不扣除、不当置信区间。A报告虽也包含2002年出生，但seed与抽样设计不同，不能直接当本实验对照。</p><p>完成采集：__FINISHED__；摘要SHA-256：<code style="overflow-wrap:anywhere">__HASH__</code></p>__DOWNLOADS__<p class="note">复算：下载脚本去掉d_前缀，放回项目scripts/；保留experiments/D_era，运行python3 scripts/analyze_era_report.py，再运行python3 scripts/build_era_report.py。需同时保留analyze_policy_reports.py统计函数与policy_report.template.html样式文件。</p></section></main><script>const D=__DATA__;
const $=id=>document.getElementById(id),fmt=x=>x==null?'—':Number(x).toLocaleString('zh-CN',{maximumFractionDigits:0}),pct=x=>x==null?'—':(x*100).toFixed(1)+'%',dec=x=>x==null?'—':x.toFixed(2),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function table(head,rows){return '<table><thead><tr>'+head.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function render(){let iso=$('iso').value,age=$('age').value,by=+$('cohort').value,get=(b,m)=>D.groups.find(r=>r.iso===iso&&r.by===b&&r.age===age&&r.metric===m);$('money').innerHTML=table(['出生年','对应日历年','快照/出生数','月收入中位/元','净资产P10 / 中位 / P90元','净资产为负','净资产/中位年收入','年收入/中位年收入'],D.cohorts.map(b=>{let r=get(b,'nw'),y=age==='death'?null:b+(+age);return [b,y==null?'各自死亡年':y+(y>2026?' · 未来模拟':''),r.n+'/1000',fmt(get(b,'income').median),[r.p10,r.median,r.p90].map(fmt).join(' / '),pct(r.negative),dec(get(b,'nwMed').median),dec(get(b,'incMed').median)]}));
$('pairs').innerHTML=table(['出生年减2002','配对数','净资产差P10 / 中位 / P90元','净资产差均值/元','月收入差中位/元','幸福差中位'],D.cohorts.filter(b=>b!==2002).map(b=>{let g=m=>D.pairs.find(r=>r.iso===iso&&r.by===b&&r.age===age&&r.metric===m),r=g('nw');return [b,r.n+(r.n<30?' ⚠ 小样本':''),[r.p10,r.median,r.p90].map(fmt).join(' / '),fmt(r.mean),fmt(g('income').median),dec(g('h').median)]}));
$('flow').innerHTML=table(['出生年','计划','2002组缺快照','该组缺快照','双方可比'],D.flows.filter(r=>r.iso===iso&&r.age===age).map(r=>[r.by,r.planned,r.base_missing,r.cohort_missing,r.both]));$('common').innerHTML=table(['出生年','共同样本','净资产中位/元'],D.common.filter(r=>r.iso===iso&&r.age===age).map(r=>[r.by,r.n+(r.n<30?' ⚠ 小样本':''),fmt(r.median)]));
$('life').innerHTML=table(['出生年','出生数','享年中位 / 均值','活到5岁','高等教育','摘要子女均值','去世年>2026'],D.cells.filter(r=>r.iso===iso).map(r=>[r.by,r.n,dec(r.life_median)+' / '+dec(r.life_mean),pct(r.survive5),pct(r.higher_edu),dec(r.kids_mean),pct(r.future_death)]));$('lifepairs').innerHTML=table(['出生年减2002','配对数','寿命差P10 / 中位 / P90','均值'],D.life_pairs.filter(r=>r.iso===iso&&r.by!==2002).map(r=>[r.by,r.n,[r.p10,r.median,r.p90].map(dec).join(' / '),dec(r.mean)]));$('survival').innerHTML=age==='death'?'终局不是固定年龄；完整终局分母为每格1,000。':table(['出生年','达到年龄人数 / 出生数','比例'],D.survival.filter(r=>r.iso===iso&&r.age===age).map(r=>[r.by,r.reached+'/1000',pct(r.reached/1000)]));
let hh=D.history.filter(r=>r.iso===iso&&r.by===by).sort((a,b)=>b.events-a.events||a.text.localeCompare(b.text)).slice(0,20);$('hist').innerHTML=hh.length?table(['历史文本','出现人数/1000','条目次数'],hh.map(r=>['<div style="white-space:normal;min-width:320px;max-width:760px">'+esc(r.text)+'</div>',r.people,r.events])):'该格没有kind=hist记录；不代表没有历史影响。';$('items').innerHTML=table(['物品','终局保留记录/出生数','缺记录人数','记录年龄P10 / 中位 / P90','记录比例'],D.items.filter(r=>r.iso===iso&&r.by===by).map(r=>[{phone:'智能手机',pc:'电脑',car:'汽车',house:'住房'}[r.item],r.n+'/1000',1000-r.n,[r.p10,r.median,r.p90].map(dec).join(' / '),pct(r.retained_rate)]));$('audit').innerHTML=table(['出生年','性别变化','家境变化','天分变化'],D.audit.filter(r=>r.iso===iso).map(r=>[r.by,r.sex_changed,r.q_changed,r.tal_changed]));}
$('iso').innerHTML=Object.entries(D.countries).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('');$('cohort').innerHTML=D.cohorts.map(b=>'<option'+(b===2002?' selected':'')+'>'+b+'</option>').join('');$('caseList').innerHTML=D.cases.map(c=>'<details><summary>'+D.countries[c.iso]+' · '+esc(c.seed)+' · 1960减2002寿命差 '+c.difference+'岁</summary><div class="two">'+c.lives.map(l=>'<div class="panel"><h3>'+l.by+'年出生 · '+esc(l.name)+' · 享年'+l.age+'</h3><p>'+esc(l.id)+'</p><div class="log">'+l.log.map(z=>'<p><b>'+esc(z.a)+'岁</b> '+esc(z.text)+'</p>').join('')+'</div></div>').join('')+'</div></details>').join('');['iso','age','cohort'].forEach(id=>$(id).addEventListener('change',render));render();</script></body></html>'''
f=f'''<div class="grid"><div class="panel"><h3>中国：完整出生队列享年均值</h3><p>1950年出生 <b>{c[1950]['life_mean']:.1f}</b> 岁，2002年出生 <b>{c[2002]['life_mean']:.1f}</b> 岁，2020年出生 <b>{c[2020]['life_mean']:.1f}</b> 岁。包含婴幼儿死亡，也包含未来模拟部分。</p></div><div class="panel"><h3>中国：活到5岁的比例</h3><p>1950年出生 {c[1950]['survive5']:.1%}，1960年出生 {c[1960]['survive5']:.1%}，2002年出生 {c[2002]['survive5']:.1%}。先看完整出生队列，再看幸存到某年龄者的财富。</p></div><div class="panel"><h3>2020年出生的24岁</h3><p>对应2044年。页面逐行显示日历年及未来标记，避免把不同年代的同龄财富当成同一年购买力的现实观测。</p></div></div>'''
files=sorted((R/'tables').glob('*.csv'));scripts=['analyze_era_report.py','build_era_report.py','analyze_policy_reports.py','policy_report.template.html']
for deploy in [False,True]:
 links=' · '.join(f'<a href="{"d_"+p.name if deploy else "tables/"+p.name}">{p.name}</a>' for p in files)+'<p>'+' · '.join(f'<a href="{"d_"+p if deploy else "../../scripts/"+p}">{p}</a>' for p in scripts)+'</p>';out=t
 for k,v in {'STYLE':style,'FINDINGS':f,'FINISHED':d['finishedAt'] if 'finishedAt' in d else d['finished'],'HASH':d['source_hash'],'DOWNLOADS':links,'DATA':json.dumps(d,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')}.items():out=out.replace('__'+k+'__',v)
 (pub/'D_era.html' if deploy else R/'report.html').write_text(out)
for p in files:shutil.copyfile(p,pub/('d_'+p.name))
for p in scripts:shutil.copyfile(ROOT/'scripts'/p,pub/('d_'+p))
print('D built',len(out))
